ell_names = expression_matrix.columns df_labels = pd.DataFrame({    'label': clusters['clusters'].values,    'cell_label': cell_names}, index=cell_names)#read in seurat marker genesNSmarkers =pd.read_csv("/Users/ggraham/MERFISH/NSForest Output/final_clusters2_markers.csv")ns_genes = NSmarkers['markerGene']## machine learning time babeyfrom sklearn.model_selection import cross_val_score, StratifiedKFoldfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import accuracy_scoreimport numpy as np    #pval # Prepare data - transpose so cells are rows, genes are columnsns_X = expression_matrix.loc[ns_genes].Tns_y = df_labels['label']# Initialize classifierns_clf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationns_cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)ns_cv_scores = cross_val_score(ns_clf, ns_X, ns_y, cv=ns_cv, scoring='accuracy')# Calculate metricsnp.mean(ns_cv_scores)np.std(ns_cv_scores)